 auto bound=use(2,4100,{0,0});Check(bound && bound->result.skillId==1 && bound->result.nextLevel==1,"bound target resolved from instance only");apply(*bound);auto horse=use(4,4100,{0,1000});Check(horse.has_value(),"horse point uses distinct pool");apply(*horse);Check(character.points[2]==1 && learning.progress.front().skill==0,"horse no artificial skill target");
 auto noRule=facts;noRule.targetAllowedByRules=false;Check(!MakeBookRuntimeCommit(*c,{22,70},fence,layouts,items,learning,character,items[2].id,noRule,5000,{}),"owner default-deny gate");
